syntax:
For a class with virtual functions:

class ClassName {
public:
    virtual void func();
    // ...
};

// Object layout includes:
// [Object Data Members][Pointer to vtable]
// The vtable is a static array of function pointers generated by the compiler.

// During runtime, calling a virtual function involves:
// 1. Accessing the object's vptr (vtable pointer)
// 2. Using the vptr to locate the vtable
// 3. Indexing into the vtable to find the function pointer
// 4. Invoking the function via the pointer

code_example:
class Base {
public:
    virtual void foo() {
        // Base implementation
    }
};

class Derived : public Base {
public:
    void foo() override {
        // Derived override
    }
};

int main() {
    Derived d;
    Base* pb = &d;
    pb->foo(); // Dynamic dispatch via vtable
}
